/* Riyadh public transport — bus + metro map, multimodal planner, districts, park & ride.
 * Arabic-first interface; station/stop names carry their English name alongside.
 * Data: window.RIYADH_METRO_DATA (metro) + window.RIYADH_TRANSIT_DATA (bus, districts, P&R),
 * both generated by scripts/build.js. Logic: RMNetwork (metro graph) + RMTransit (multimodal model).
 */
(function () {
  'use strict';

  var $ = function (s, r) { return (r || document).querySelector(s); };
  var $$ = function (s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)); };

  /* ────────────────────────────────────────────────────────── 1. data */
  var DATA = window.RIYADH_METRO_DATA;
  var TDATA = window.RIYADH_TRANSIT_DATA;
  if (!DATA || !TDATA || !window.RMTransit || !window.RMNetwork) {
    document.body.insertAdjacentHTML('afterbegin',
      '<div style="padding:24px;font-family:system-ui;background:#2b1414;color:#ffd9d9">' +
      'تعذّر تحميل بيانات شبكة النقل. افتح الصفحة من خلال خادم محلي (<code>npm run serve</code>) بدل فتح الملف مباشرة.' +
      '</div>');
    return;
  }

  var NET = RMNetwork.buildNetwork(DATA);
  var MODEL = RMTransit.build({
    network: NET,
    bus: TDATA.bus,
    districts: TDATA.districts,
    parkAndRide: TDATA.parkAndRide,
    config: DATA.config
  });
  var CFG = DATA.config || {};
  var S = MODEL.stats;
  var PR = MODEL.parkAndRide;
  var GEO = window.RMGeo;

  var TYPES = {
    brt: { ar: 'نقل سريع', long: 'حافلات النقل السريع (BRT)', color: '#E8552D' },
    main: { ar: 'مسار رئيسي', long: 'المسارات الرئيسية', color: '#2D7DD2' },
    sector: { ar: 'مسار قطاعي', long: 'مسارات القطاعات', color: '#2FA37C' },
    community: { ar: 'مسار تغذية', long: 'المسارات التغذوية (المجتمعية)', color: '#7C8794' }
  };
  var SHELTER = {
    brt: { ar: 'محطة نقل سريع', short: 'BRT' },
    ac: { ar: 'مأوى مكيّف', short: 'مكيّف' },
    'ac-large': { ar: 'مأوى مكيّف كبير', short: 'مكيّف كبير' },
    open: { ar: 'مأوى مفتوح', short: 'مفتوح' },
    pole: { ar: 'عمود تغذية', short: 'عمود' },
    'pole-standard': { ar: 'عمود تغذية (تجهيز قياسي)', short: 'عمود' },
    metro: { ar: 'محطة مترو', short: 'مترو' },
    terminal: { ar: 'محطة طرفية', short: 'طرفية' },
    unknown: { ar: 'غير محدد', short: '—' }
  };
  var STAGE_LABEL = function (stage, operating) {
    if (!operating) return 'مرحلة قادمة';
    if (!stage) return 'قيد التشغيل';
    return 'مرحلة ' + stage;
  };

  /* helpers ----------------------------------------------------------------- */
  function fmt(n) { return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }
  function nm(n) { return n ? (n.ar || n.en || '') : ''; }
  function ne(n) { return n ? (n.en || n.ar || '') : ''; }
  function dist(m) { return GEO.formatDistance(m, 'ar'); }
  function km(m) { return (m / 1000).toFixed(m < 10000 ? 1 : 0); }
  function mins(n) { return n === 1 ? 'دقيقة' : n === 2 ? 'دقيقتان' : (n >= 3 && n <= 10 ? n + ' دقائق' : n + ' دقيقة'); }
  function stopName(id) { var s = MODEL.stops[id]; return s ? nm(s.name) : id; }
  function stationName(id) { var s = NET.stations[id]; return s ? nm(s.name) : id; }
  function safeGet(k) { try { return localStorage.getItem(k); } catch (e) { return null; } }
  function safeSet(k, v) { try { localStorage.setItem(k, v); } catch (e) { /* private mode */ } }
  function isLight() { return document.documentElement.getAttribute('data-theme') === 'light'; }

  var toastTimer = null;
  function toast(msg) {
    var el = $('#pt-toast');
    el.textContent = msg;
    el.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { el.classList.remove('show'); }, 3200);
  }

  /* ────────────────────────────────────────────────────────── 2. state */
  var state = {
    theme: document.documentElement.getAttribute('data-theme') || 'dark',
    tab: 'plan',
    from: null,
    to: null,
    modes: ['metro', 'bus', 'walk'],
    alts: [],
    itIndex: 0,
    route: null,
    routeDir: null,
    district: null,
    stop: null,
    station: null,
    busQuery: '',
    busFilter: 'all',
    areaQuery: '',
    layers: { metro: true, bus: true, stops: true, districts: false, parking: true, labels: false }
  };

  /* ────────────────────────────────────────────────────────── 3. map */
  var map = L.map('pt-map', { zoomControl: false, minZoom: 10, maxZoom: 19, preferCanvas: true, attributionControl: true })
    .setView([24.7136, 46.6753], 11);

  var baseLayers = {
    dark: L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
      maxZoom: 19, subdomains: 'abcd',
      attribution: '&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> &copy; <a href="https://carto.com/" target="_blank" rel="noopener">CARTO</a>'
    }),
    light: L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
      maxZoom: 19, subdomains: 'abcd',
      attribution: '&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> &copy; <a href="https://carto.com/" target="_blank" rel="noopener">CARTO</a>'
    })
  };
  var base = baseLayers[isLight() ? 'light' : 'dark'];
  base.addTo(map);

  var canvas = L.canvas({ padding: 0.4 });
  var groups = {
    districts: L.layerGroup(),
    bus: L.layerGroup(),
    metro: L.layerGroup(),
    stops: L.layerGroup(),
    parking: L.layerGroup(),
    labels: L.layerGroup(),
    highlight: L.layerGroup(),
    journey: L.layerGroup()
  };
  Object.keys(groups).forEach(function (k) { groups[k].addTo(map); });

  var ROUTE_COLOR = {};
  MODEL.routeOrder.forEach(function (id) { ROUTE_COLOR[id] = MODEL.routes[id].color || TYPES[MODEL.routes[id].type].color; });

  function metroGeometry(line) {
    var pts = [];
    (line.segments || []).forEach(function (sg) {
      (sg.geometry || []).forEach(function (p, i) {
        if (i === 0 && pts.length) return;
        pts.push(p);
      });
    });
    return pts;
  }

  function drawMetro() {
    groups.metro.clearLayers();
    NET.lineOrder.forEach(function (lid) {
      var line = NET.lines[lid];
      var pts = metroGeometry(line);
      if (pts.length < 2) return;
      var pl = L.polyline(pts, {
        color: line.color, weight: 4.6, opacity: 0.95, lineCap: 'round', lineJoin: 'round', renderer: canvas
      });
      pl.bindTooltip(nm(line.name) + ' · ' + line.stations.length + ' محطة', { sticky: true, direction: 'top' });
      pl.on('click', function () { toast(nm(line.name) + ' — ' + nm(line.termini.first) + ' ← ' + nm(line.termini.last)); });
      pl.addTo(groups.metro);
    });
    NET.lineOrder.forEach(function (lid) {
      var line = NET.lines[lid];
      line.stations.forEach(function (sid) {
        var st = NET.stations[sid];
        L.circleMarker([st.lat, st.lng], {
          radius: 4.6, color: '#fff', weight: 1.4, fillColor: line.color, fillOpacity: 1, renderer: canvas
        }).bindTooltip(nm(st.name), { direction: 'top', offset: [0, -4] })
          .on('click', function () { openStation(sid); })
          .addTo(groups.metro);
      });
    });
  }

  function drawBusRoutes() {
    groups.bus.clearLayers();
    MODEL.routeOrder.forEach(function (rid) {
      var route = MODEL.routes[rid];
      var color = ROUTE_COLOR[rid];
      Object.keys(route.dirs).forEach(function (dir) {
        var d = route.dirs[dir];
        if (!d || !d.shape || d.shape.length < 2) return;
        var pl = L.polyline(d.shape, {
          color: color, weight: 2.6, opacity: 0.5, lineCap: 'round', lineJoin: 'round', renderer: canvas
        });
        pl.on('click', function () { focusRoute(rid); });
        pl.addTo(groups.bus);
      });
    });
  }

  function drawDistricts() {
    groups.districts.clearLayers();
    var features = MODEL.districtOrder.map(function (id) {
      var d = MODEL.districts[id];
      return { type: 'Feature', properties: { id: id, stops: d.stops }, geometry: d.geometry };
    });
    L.geoJSON({ type: 'FeatureCollection', features: features }, {
      renderer: canvas,
      style: function (f) {
        return {
          color: f.properties.stops ? '#2FA37C' : '#7C8794',
          weight: 1,
          opacity: 0.55,
          fillColor: '#2FA37C',
          fillOpacity: f.properties.stops ? 0.07 : 0.02,
          dashArray: MODEL.districts[f.properties.id].approx ? '4 3' : null
        };
      },
      onEachFeature: function (f, layer) {
        layer.bindTooltip(MODEL.districts[f.properties.id].name.ar + ' · ' + f.properties.stops + ' محطة', { sticky: true });
        layer.on('click', function () { focusDistrict(f.properties.id); });
      }
    }).addTo(groups.districts);
  }

  function stopColor(s) {
    if (s.shelter === 'brt') return '#E8552D';
    if (s.shelter === 'metro') return '#1f1f1f';
    if (!s.operating) return '#7C8794';
    return '#2D7DD2';
  }

  function stopMarker(s, opts) {
    opts = opts || {};
    var m = L.circleMarker([s.lat, s.lng], {
      radius: opts.radius || 4,
      color: '#fff', weight: opts.weight || 1,
      fillColor: stopColor(s), fillOpacity: s.operating ? 1 : 0.45,
      renderer: canvas
    });
    if (opts.tip !== false) {
      m.bindTooltip(nm(s.name) + (s.routes.length ? ' · ' + s.routes.length + ' مسار' : ''), { direction: 'top', offset: [0, -3] });
    }
    m.on('click', function () { openStop(s.id); });
    return m;
  }

  var stopsDrawn = 0;
  function refreshStops(force) {
    groups.stops.clearLayers();
    stopsDrawn = 0;
    if (!state.layers.stops || map.getZoom() < 13) return;
    var b = map.getBounds();
    var max = 1600;
    for (var i = 0; i < MODEL.stopOrder.length && stopsDrawn < max; i++) {
      var s = MODEL.stops[MODEL.stopOrder[i]];
      if (s.lat < b.getSouth() - 0.002 || s.lat > b.getNorth() + 0.002) continue;
      if (s.lng < b.getWest() - 0.002 || s.lng > b.getEast() + 0.002) continue;
      stopMarker(s, { radius: map.getZoom() >= 16 ? 5 : 4, tip: map.getZoom() >= 15 }).addTo(groups.stops);
      stopsDrawn++;
    }
    if (stopsDrawn >= max) toast('يتم عرض ' + fmt(max) + ' محطة. قرّب الخريطة لرؤية الباقي.');
  }

  function drawParking() {
    groups.parking.clearLayers();
    PR.sites.forEach(function (site) {
      var icon = L.divIcon({
        className: '', iconSize: [28, 28], iconAnchor: [14, 14],
        html: '<div class="pt-pin par"><span>P</span></div>'
      });
      var m = L.marker([site.lat, site.lng], { icon: icon, title: nm(site.name) });
      m.bindTooltip('🅿️ ' + nm(site.name) + (site.capacity ? ' · ' + fmt(site.capacity) + ' موقف' : ''), { direction: 'top', offset: [0, -8] });
      m.on('click', function () { openParking(site); });
      m.addTo(groups.parking);
    });
  }

  function drawLabels() {
    groups.labels.clearLayers();
    if (!state.layers.labels || map.getZoom() < 12) return;
    var b = map.getBounds();
    MODEL.districtOrder.slice(0, 133).forEach(function (id) {
      var d = MODEL.districts[id];
      var c = d.centroid;
      if (!c || !b.contains([c[0], c[1]])) return;
      var icon = L.divIcon({
        className: '', iconSize: [0, 0],
        html: '<div class="pt-district-label">' + esc(d.name.ar) + ' <b>' + d.stops + '</b></div>'
      });
      L.marker(c, { icon: icon, interactive: true, keyboard: false })
        .on('click', function () { focusDistrict(id); })
        .addTo(groups.labels);
    });
  }

  function applyLayers() {
    Object.keys(groups).forEach(function (k) {
      if (k === 'highlight' || k === 'journey') return;
      if (state.layers[k]) groups[k].addTo(map); else map.removeLayer(groups[k]);
    });
    if (state.layers.stops) refreshStops(true);
    drawLabels();
  }

  map.on('moveend', function () { refreshStops(); });
  map.on('zoomend', function () { drawLabels(); refreshStops(); });

  /* ────────────────────────────────────────────────── 4. map selection */
  var highlight = { route: null, district: null, stop: null, station: null };

  function clearHighlight(except) {
    Object.keys(highlight).forEach(function (k) {
      if (k === except || !highlight[k]) return;
      groups.highlight.removeLayer(highlight[k]);
      highlight[k] = null;
    });
  }

  function setHighlight(kind, layer) {
    clearHighlight(kind);
    highlight[kind] = layer.addTo(groups.highlight);
  }

  function fitPoints(pts, pad) {
    if (!pts.length) return;
    map.fitBounds(L.latLngBounds(pts), { padding: pad || [30, 30], maxZoom: 15 });
  }

  function focusRoute(rid, opts) {
    var route = MODEL.routes[rid];
    if (!route) return;
    opts = opts || {};
    state.route = rid;
    state.routeDir = opts.dir || state.routeDir || null;
    if (!route.dirs[state.routeDir]) state.routeDir = Object.keys(route.dirs)[0];
    clearHighlight('route');
    var d = route.dirs[state.routeDir];
    var line = L.polyline(d.shape, {
      color: ROUTE_COLOR[rid], weight: 6, opacity: 0.95, lineCap: 'round', lineJoin: 'round'
    }).addTo(groups.highlight);
    highlight.route = line;
    d.stops.forEach(function (sid) {
      var s = MODEL.stops[sid];
      if (!s) return;
      L.circleMarker([s.lat, s.lng], {
        radius: 4, color: '#fff', weight: 1.2, fillColor: ROUTE_COLOR[rid], fillOpacity: 1
      }).bindTooltip(nm(s.name), { direction: 'top' })
        .on('click', function () { openStop(sid); })
        .addTo(groups.highlight);
    });
    if (opts.fit !== false) fitPoints(d.shape);
    line.bindTooltip(rid + ' · ' + nm(route.name), { sticky: true, direction: 'top' });
    renderBusDetail();
    renderBusList();
    switchTab('bus');
    setHash('r=' + rid + (state.routeDir !== route.directions[0] ? '&d=' + state.routeDir : ''));
    showMapStatus('المسار ' + rid + ' · ' + nm(route.name) + ' · ' + route.stopCount + ' محطة');
  }

  function focusDistrict(id, opts) {
    var d = MODEL.districts[id];
    if (!d) return;
    opts = opts || {};
    state.district = id;
    clearHighlight('district');
    var layer = L.geoJSON(d.geometry, {
      style: function () { return { color: '#2FA37C', weight: 2.4, opacity: 0.95, fillColor: '#2FA37C', fillOpacity: 0.16 }; }
    }).addTo(groups.highlight);
    highlight.district = layer;
    if (opts.fit !== false) {
      var pts = [];
      var g = d.geometry;
      var rings = g.type === 'Polygon' ? g.coordinates : [].concat.apply([], g.coordinates);
      rings.forEach(function (ring) { ring.forEach(function (p) { pts.push([p[1], p[0]]); }); });
      fitPoints(pts, [40, 40]);
    }
    renderAreaDetail();
    renderAreaList();
    switchTab('areas');
    setHash('a=' + id);
    showMapStatus('حي ' + nm(d.name) + ' · ' + d.stops + ' محطة · ' + d.routes.length + ' مسار');
  }

  function openStop(id, opts) {
    var s = MODEL.stops[id];
    if (!s) return;
    opts = opts || {};
    state.stop = id;
    state.station = null;
    clearHighlight('stop');
    var m = L.circleMarker([s.lat, s.lng], { radius: 9, color: '#fff', weight: 2.5, fillColor: ROUTE_COLOR[s.routes[0]] || '#2D7DD2', fillOpacity: 1 })
      .addTo(groups.highlight);
    highlight.stop = m;
    if (opts.fit !== false) map.setView([s.lat, s.lng], Math.max(map.getZoom(), 15));
    var routes = s.routes.map(function (rid) { return MODEL.routes[rid]; }).filter(Boolean);
    var html = '<div class="pt-pop">'
      + '<b>' + esc(nm(s.name)) + '</b>'
      + '<small dir="ltr">' + esc(ne(s.name)) + '</small>'
      + '<p>' + (s.operating ? 'قيد التشغيل' : 'مرحلة قادمة') + ' · ' + (SHELTER[s.shelter] ? SHELTER[s.shelter].ar : 'محطة') + '</p>'
      + '<p>الحي: ' + esc(MODEL.districts[s.district] ? nm(MODEL.districts[s.district].name) : '—') + '</p>'
      + (s.nearMetro ? '<p>قريب من محطة مترو ' + esc(stationName(s.nearMetro.station)) + ' (' + dist(s.nearMetro.distanceM) + ')</p>' : '')
      + (routes.length ? '<div class="pt-pop-routes">' + routes.map(function (r) {
        return '<button data-act="route" data-id="' + r.id + '" style="background:' + r.color + ';color:' + (r.id === '4' ? '#1a1a00' : '#fff') + '">' + r.id + '</button>';
      }).join('') + '</div>' : '<p>لا يخدمها أي مسار منشور.</p>')
      + '<div class="pt-pop-actions">'
      + '<button data-act="from-stop" data-id="' + id + '">ابدأ من هنا</button>'
      + '<button data-act="to-stop" data-id="' + id + '">إلى هنا</button>'
      + '</div></div>';
    L.popup({ maxWidth: 300, className: 'pt-popup' })
      .setLatLng([s.lat, s.lng])
      .setContent(html)
      .openOn(map);
    renderStopCard(s);
    switchTab('plan');
    showMapStatus('محطة توقّف ' + nm(s.name) + ' · ' + routes.length + ' مسار');
  }

  function openStation(id, opts) {
    var st = NET.stations[id];
    if (!st) return;
    opts = opts || {};
    state.station = id;
    state.stop = null;
    clearHighlight('station');
    highlight.station = L.circleMarker([st.lat, st.lng], { radius: 10, color: '#fff', weight: 2.5, fillColor: '#1f1f1f', fillOpacity: 1 })
      .addTo(groups.highlight);
    if (opts.fit !== false) map.setView([st.lat, st.lng], Math.max(map.getZoom(), 15));
    var near = MODEL.stationStops[id] || [];
    var routes = {};
    near.forEach(function (x) { MODEL.stops[x.stop].routes.forEach(function (r) { routes[r] = true; }); });
    var pr = PR.byStation[id];
    var html = '<div class="pt-pop">'
      + '<b>' + esc(nm(st.name)) + '</b><small dir="ltr">' + esc(ne(st.name)) + '</small>'
      + '<p>' + st.lines.map(function (l) { return esc(nm(NET.lines[l].name)); }).join(' · ') + '</p>'
      + '<p>' + (near.length ? near.length + ' محطة حافلات قريبة · ' + Object.keys(routes).length + ' مسار' : 'لا توجد محطات حافلات ضمن 450 م') + '</p>'
      + (pr ? '<p>🅿️ موقف اركن واركب' + (pr.capacity ? ' · ' + fmt(pr.capacity) + ' موقفاً' : '') + '</p>' : '')
      + '<div class="pt-pop-actions">'
      + '<button data-act="from-station" data-id="' + id + '">ابدأ من هنا</button>'
      + '<button data-act="to-station" data-id="' + id + '">إلى هنا</button>'
      + '</div></div>';
    L.popup({ maxWidth: 300, className: 'pt-popup' }).setLatLng([st.lat, st.lng]).setContent(html).openOn(map);
    renderStationCard(st, near, routes, pr);
    switchTab('plan');
    showMapStatus('محطة ' + nm(st.name) + ' · ' + near.length + ' موقف باص قريب');
  }

  function openParking(site) {
    var html = '<div class="pt-pop"><b>🅿️ ' + esc(nm(site.name)) + '</b>'
      + '<p>' + (site.capacity ? '<b>' + fmt(site.capacity) + '</b> موقفاً' : 'السعة غير منشورة') + ' · ' + (site.lines || []).map(function (l) { return 'المسار ' + l; }).join(' · ') + '</p>'
      + '<p>' + (site.note ? esc(nm(site.note)) : 'موقف اركن واركب مرتبط بمحطة المترو.') + '</p>'
      + '<div class="pt-pop-actions"><button data-act="from-station" data-id="' + site.station + '">ابدأ من المحطة</button></div></div>';
    L.popup({ maxWidth: 280 }).setLatLng([site.lat, site.lng]).setContent(html).openOn(map);
  }

  /* popup action delegation */
  $('#pt-map').addEventListener('click', function (e) {
    var btn = e.target.closest('[data-act]');
    if (!btn) return;
    var act = btn.getAttribute('data-act');
    var id = btn.getAttribute('data-id');
    if (act === 'route') { map.closePopup(); focusRoute(id); }
    else if (act === 'from-stop') { setEndpoint('from', { kind: 'stop', id: id }); map.closePopup(); }
    else if (act === 'to-stop') { setEndpoint('to', { kind: 'stop', id: id }); map.closePopup(); }
    else if (act === 'from-station') { setEndpoint('from', { kind: 'station', id: id }); map.closePopup(); }
    else if (act === 'to-station') { setEndpoint('to', { kind: 'station', id: id }); map.closePopup(); }
  });

  var statusTimer = null;
  function showMapStatus(html) {
    var el = $('#pt-map-status');
    el.innerHTML = html;
    el.classList.add('show');
    clearTimeout(statusTimer);
    statusTimer = setTimeout(function () { el.classList.remove('show'); }, 6000);
  }

  /* ────────────────────────────────────────────────── 5. planner */
  function refName(ref) {
    if (!ref) return '';
    if (ref.name) return nm(ref.name);
    if (ref.kind === 'stop') return stopName(ref.id);
    if (ref.kind === 'station') return stationName(ref.id);
    return '';
  }

  function toRef(item) {
    if (item.kind === 'district') return { kind: 'coord', name: item.name, lat: item.lat, lng: item.lng, district: item.id, approx: true };
    if (item.kind === 'stop' || item.kind === 'station') return { kind: item.kind, id: item.id, name: item.name, lat: item.lat, lng: item.lng };
    return null;
  }

  function setEndpoint(side, ref) {
    state[side] = ref;
    $('#pt-' + side).value = refName(ref);
    $('#pt-' + side).dataset.id = ref ? ref.kind + ':' + (ref.id || (ref.lat + ',' + ref.lng)) : '';
    state.alts = [];
    if (state.from && state.to) planJourney();
    else renderResults();
  }

  var KIND_ICON = { station: '🚇', stop: '🚌', route: '🛣️', district: '🏘️', place: '📍' };
  function kindMeta(item) {
    if (item.kind === 'station') return (item.lines || []).map(function (l) { return 'مترو ' + l; }).join(' · ');
    if (item.kind === 'stop') {
      var d = item.district && MODEL.districts[item.district];
      return (item.routes.length ? item.routes.length + ' مسار' : 'بدون مسار') + (d ? ' · ' + nm(d.name) : '') + ' · ' + item.id.replace(/^b/, '');
    }
    if (item.kind === 'route') return TYPES[item.type].long + ' · ' + nm(item.name);
    if (item.kind === 'district') return 'حي · ' + item.stops + ' محطة توقّف';
    if (item.kind === 'place') return 'معلم · ' + (NET.stations[item.station] ? nm(NET.stations[item.station].name) : '');
    return '';
  }

  function renderSuggest(box, items, onPick) {
    box.innerHTML = items.map(function (it, i) {
      return '<div role="option" data-idx="' + i + '" tabindex="-1">'
        + '<span class="pico">' + (KIND_ICON[it.kind] || '📍') + '</span>'
        + '<span>' + esc(nm(it.name)) + (it.kind === 'stop' || it.kind === 'station' ? ' <small>' + esc(ne(it.name)) + '</small>' : '')
        + '<small class="sub">' + esc(kindMeta(it)) + '</small></span></div>';
    }).join('');
    box.classList.toggle('open', items.length > 0);
    box._items = items;
    box._onPick = onPick;
    $$('[role="option"]', box).forEach(function (el) {
      el.addEventListener('mousedown', function (e) { e.preventDefault(); });
      el.addEventListener('click', function () {
        var it = items[+el.dataset.idx];
        box.classList.remove('open');
        onPick(it);
      });
    });
  }

  function setupSuggest(input, box, onPick) {
    var active = -1;
    function run() {
      var q = input.value.trim();
      if (!q) { box.classList.remove('open'); box._items = []; return; }
      var items = RMTransit.search(MODEL, q, 8);
      renderSuggest(box, items, onPick);
      active = -1;
    }
    input.addEventListener('input', run);
    input.addEventListener('focus', function () { if (input.value.trim()) run(); });
    input.addEventListener('keydown', function (e) {
      var items = box._items || [];
      if (!items.length || !box.classList.contains('open')) return;
      if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        e.preventDefault();
        active += e.key === 'ArrowDown' ? 1 : -1;
        if (active < 0) active = items.length - 1;
        if (active >= items.length) active = 0;
        $$('[role="option"]', box).forEach(function (el, i) { el.classList.toggle('active', i === active); });
      } else if (e.key === 'Enter' && active >= 0) {
        e.preventDefault();
        var it = items[active];
        box.classList.remove('open');
        onPick(it);
      } else if (e.key === 'Escape') { box.classList.remove('open'); }
    });
    input.addEventListener('blur', function () { setTimeout(function () { box.classList.remove('open'); }, 160); });
  }

  function pickEndpoint(side) {
    return function (item) {
      if (item.kind === 'route') { focusRoute(item.id); return; }
      setEndpoint(side, toRef(item));
      $('#pt-' + side).blur();
      if (state.from && state.to) planJourney();
    };
  }

  setupSuggest($('#pt-from'), $('#pt-from-suggest'), pickEndpoint('from'));
  setupSuggest($('#pt-to'), $('#pt-to-suggest'), pickEndpoint('to'));

  $('#pt-swap').addEventListener('click', function () {
    var f = state.from;
    state.from = state.to;
    state.to = f;
    $('#pt-from').value = refName(state.from);
    $('#pt-to').value = refName(state.to);
    if (state.from && state.to) planJourney(); else renderResults();
  });

  $('#pt-clear').addEventListener('click', function () {
    state.to = null;
    $('#pt-to').value = '';
    state.alts = [];
    renderResults();
    $('#pt-to').focus();
  });

  $('#pt-form').addEventListener('submit', function (e) {
    e.preventDefault();
    /* typing without picking a suggestion: resolve the best match */
    if (!state.from && $('#pt-from').value.trim()) {
      var r1 = RMTransit.search(MODEL, $('#pt-from').value, 1)[0];
      if (r1) setEndpoint('from', toRef(r1));
    }
    if (!state.to && $('#pt-to').value.trim()) {
      var r2 = RMTransit.search(MODEL, $('#pt-to').value, 1)[0];
      if (r2) setEndpoint('to', toRef(r2));
    }
    planJourney();
  });

  $$('input[name="pt-mode"]').forEach(function (r) {
    r.addEventListener('change', function () {
      var v = r.value;
      state.modes = v === 'metro' ? ['metro', 'walk'] : v === 'bus' ? ['bus', 'walk'] : ['metro', 'bus', 'walk'];
      if (state.from && state.to) planJourney();
    });
  });

  $('#pt-locate').addEventListener('click', function () { locate(true); });
  $('#pt-find').addEventListener('click', function () { locate(false); });

  function locate(plan) {
    if (!navigator.geolocation) { toast('المتصفح لا يدعم تحديد الموقع.'); return; }
    toast('جارٍ تحديد موقعك…');
    navigator.geolocation.getCurrentPosition(function (pos) {
      var lat = pos.coords.latitude, lng = pos.coords.longitude;
      if (lat < 24.1 || lat > 25.4 || lng < 46.0 || lng > 47.7) { toast('موقعك خارج نطاق مدينة الرياض.'); return; }
      map.setView([lat, lng], 15);
      L.circleMarker([lat, lng], { radius: 7, color: '#fff', weight: 2, fillColor: '#d3f17b', fillOpacity: 1 }).addTo(groups.highlight);
      var near = RMTransit.nearby(MODEL, lat, lng, 5, 900);
      if (near.length) {
        toast('أقرب محطة: ' + nm(near[0].item.name) + ' (' + dist(near[0].distanceM) + ')');
      }
      if (plan) {
        state.from = { kind: 'coord', name: { ar: 'موقعي الحالي', en: 'My location' }, lat: lat, lng: lng };
        $('#pt-from').value = 'موقعي الحالي';
        if (state.to) planJourney(); else $('#pt-to').focus();
      }
    }, function () { toast('تعذّر الوصول إلى موقعك. تحقّق من إذن الموقع.'); }, { enableHighAccuracy: true, timeout: 12000, maximumAge: 60000 });
  }

  /* ────────────────────────────────────────────── 6. itinerary rendering */
  function planJourney() {
    if (!state.from || !state.to) {
      renderResults();
      if (!state.from) $('#pt-from').focus(); else $('#pt-to').focus();
      return;
    }
    var opts = { modes: state.modes.slice() };
    var alts = RMTransit.alternatives(MODEL, state.from, state.to, opts);
    if (!alts.length && state.modes.length < 3) {
      alts = RMTransit.alternatives(MODEL, state.from, state.to, { modes: ['metro', 'bus', 'walk'] });
      if (alts.length) toast('لا توجد رحلة بالوسيلة المختارة — عُرضت أفضل رحلة بكل الوسائل.');
    }
    state.alts = alts;
    state.itIndex = 0;
    renderResults();
    if (alts.length) {
      drawJourney(alts[0]);
      setHash('f=' + encodeRef(state.from) + '~' + encodeRef(state.to) + '&m=' + modeSlug());
    } else {
      clearJourney();
      showMapStatus('لا توجد رحلة بين النقطتين بالوسائل المختارة.');
    }
  }

  function modeSlug() {
    if (state.modes.indexOf('bus') < 0) return 'metro';
    if (state.modes.indexOf('metro') < 0) return 'bus';
    return 'all';
  }

  function encodeRef(ref) {
    if (!ref) return '';
    if (ref.kind === 'station' || ref.kind === 'stop') return ref.kind + ':' + ref.id;
    return 'co:' + ref.lat.toFixed(5) + ',' + ref.lng.toFixed(5);
  }
  function decodeRef(token) {
    if (!token) return null;
    var parts = String(token).split(':');
    if (parts[0] === 'station' && NET.stations[parts[1]]) return { kind: 'station', id: parts[1], name: NET.stations[parts[1]].name };
    if (parts[0] === 'stop' && MODEL.stops[parts[1]]) return { kind: 'stop', id: parts[1], name: MODEL.stops[parts[1]].name };
    if (parts[0] === 'co') {
      var c = parts[1].split(',');
      return { kind: 'coord', lat: +c[0], lng: +c[1], name: { ar: 'نقطة على الخريطة', en: 'Map point' } };
    }
    return null;
  }

  function modeLabel(it) {
    if (it.mode === 'fewest-transfers') return 'أقل تبديلاً';
    if (it.modes.length === 1 && it.modes[0] === 'metro') return 'مترو فقط';
    if (it.modes.length === 1 && it.modes[0] === 'bus') return 'حافلات فقط';
    return 'الأسرع';
  }

  function renderResults() {
    var box = $('#pt-results');
    var empty = $('#pt-plan-empty');
    if (!state.alts.length) {
      box.innerHTML = state.from && state.to ? noRouteHtml() : '';
      empty.hidden = !!box.innerHTML;
      if (!box.innerHTML) empty.hidden = false;
      return;
    }
    empty.hidden = true;
    var it = state.alts[Math.min(state.itIndex, state.alts.length - 1)] || state.alts[0];
    var head = '<div class="pt-result-head"><b>' + esc(refName(state.from)) + ' ← ' + esc(refName(state.to)) + '</b>'
      + '<span>' + state.alts.length + ' خيارات</span></div>';
    var alts = state.alts.length > 1 ? '<div class="pt-alts">' + state.alts.map(function (a, i) {
      return '<button data-i="' + i + '" aria-pressed="' + (i === state.itIndex) + '"><b>' + a.totalMinutes + ' د</b><small>' + modeLabel(a) + (a.transfers ? ' · ' + a.transfers + ' تبديل' : '') + '</small></button>';
    }).join('') + '</div>' : '';
    var summary = '<div class="pt-summary">'
      + '<div class="pt-summary-top"><b>' + it.totalMinutes + '</b><span>دقيقة تقديرية</span></div>'
      + '<div class="pt-summary-meta">'
      + pill(it.modes.map(function (m) { return m === 'metro' ? '🚇 مترو' : '🚌 حافلة'; }).join(' + ') || '🚶 مشي', true)
      + pill(it.transfers + ' تبديل')
      + pill('مشي ' + it.walkMinutes + ' د')
      + pill('انتظار ' + it.waitMinutes + ' د')
      + pill('أجرة ' + it.fare + ' ر.س')
      + pill(dist(it.totalDistanceM))
      + '</div></div>';
    var steps = '<ul class="pt-steps">' + it.legs.map(legHtml).join('') + '</ul>';
    var actions = '<div class="pt-result-actions">'
      + '<button data-act="zoom-journey">اعرض على الخريطة</button>'
      + '<button data-act="swap">اعكس الرحلة</button>'
      + '<a href="' + googleLink(it) + '" target="_blank" rel="noopener">خرائط جوجل ↗</a>'
      + '<button data-act="download-journey">GeoJSON</button>'
      + '</div>';
    box.innerHTML = head + alts + summary + steps + actions;
    $$('.pt-alts button', box).forEach(function (b) {
      b.addEventListener('click', function () {
        state.itIndex = +b.dataset.i;
        renderResults();
        drawJourney(state.alts[state.itIndex]);
      });
    });
    $$('.pt-result-actions [data-act]', box).forEach(function (b) {
      b.addEventListener('click', function () {
        var act = b.dataset.act;
        if (act === 'zoom-journey') { drawJourney(it); fitJourney(it); }
        else if (act === 'swap') { $('#pt-swap').click(); }
        else if (act === 'download-journey') downloadJourney(it);
      });
    });
  }

  function noRouteHtml() {
    var from = state.from, to = state.to;
    var a = from.kind === 'coord' ? RMTransit.nearby(MODEL, from.lat, from.lng, 3, 1500) : [];
    var b = to.kind === 'coord' ? RMTransit.nearby(MODEL, to.lat, to.lng, 3, 1500) : [];
    return '<div class="pt-detail" style="margin-top:16px">'
      + '<b style="font-size:14px">لا توجد رحلة متاحة بين هاتين النقطتين</b>'
      + '<p class="hint" style="margin:8px 0">السبب الغالب: إحدى النقطتين بعيدة عن أي محطة توقّف، أو أن التبديل بين الوسائل يتجاوز مسافة المشي المسموحة.</p>'
      + (a.length ? '<p class="hint">أقرب محطات إلى الانطلاق: ' + a.map(function (x) { return esc(nm(x.item.name)) + ' (' + dist(x.distanceM) + ')'; }).join(' · ') + '</p>' : '')
      + (b.length ? '<p class="hint">أقرب محطات إلى الوصول: ' + b.map(function (x) { return esc(nm(x.item.name)) + ' (' + dist(x.distanceM) + ')'; }).join(' · ') + '</p>' : '')
      + '<div class="pt-detail-actions"><button data-act="allow-all">اسمح بكل الوسائل وأعد المحاولة</button></div>'
      + '</div>';
  }

  function pill(text, accent) { return '<span class="pt-pill' + (accent ? ' accent' : '') + '">' + esc(text) + '</span>'; }

  function legHtml(leg) {
    if (leg.type === 'walk') {
      return '<li class="pt-step"><span class="pt-step-icon walk">🚶</span><div class="pt-step-body">'
        + '<b>امشِ ' + dist(leg.meters) + ' · ' + mins(leg.minutes) + '</b>'
        + '<small>' + esc(nm(leg.fromName)) + ' ← ' + esc(nm(leg.toName)) + '</small>'
        + '</div></li>';
    }
    if (leg.type === 'metro') {
      var line = NET.lines[leg.line];
      var stationList = leg.stations.map(function (sid, i) {
        return '<li>' + esc(stationName(sid)) + (i === 0 || i === leg.stations.length - 1 ? '' : '') + '</li>';
      }).join('');
      return '<li class="pt-step"><span class="pt-step-icon metro">🚇</span><div class="pt-step-body">'
        + '<b>مترو ' + esc(nm(line.name)) + ' · ' + mins(leg.minutes) + '</b>'
        + '<small>' + esc(nm(leg.fromName)) + ' ← ' + esc(nm(leg.toName)) + ' · ' + leg.stops + ' محطة · انتظار ' + leg.waitMinutes + ' د</small>'
        + '<div class="pt-leg-badges"><span class="pt-leg-badge' + (line.id === '4' ? ' dark' : '') + '" style="background:' + line.color + '">' + esc(nm(line.name)) + '</span></div>'
        + '<details><summary>المحطات على الطريق (' + (leg.stations.length) + ')</summary><ol reversed>' + stationList + '</ol></details>'
        + '</div></li>';
    }
    var route = MODEL.routes[leg.route];
    var stopList = leg.stopsIds.map(function (sid) { return '<li>' + esc(stopName(sid)) + '</li>'; }).join('');
    var transfer = leg.transferTo ? '<div class="pt-leg-badges"><span class="pt-pill">↔ تبديل إلى ' + esc(leg.transferTo.type === 'metro' ? 'مترو ' + nm(leg.transferTo.name) : 'حافلة ' + leg.transferTo.id) + (leg.transferTo.walkM > 30 ? ' · مشي ' + dist(leg.transferTo.walkM) : '') + '</span></div>' : '';
    return '<li class="pt-step"><span class="pt-step-icon bus" style="background:' + route.color + '">🚌</span><div class="pt-step-body">'
      + '<b>حافلة ' + esc(route.id) + ' · ' + mins(leg.minutes) + '</b>'
      + '<small>' + esc(nm(leg.fromName)) + ' ← ' + esc(nm(leg.toName)) + ' · ' + leg.stops + ' محطة · كل ' + route.headwayMin + ' د · انتظار ' + leg.waitMinutes + ' د</small>'
      + '<div class="pt-leg-badges"><span class="pt-leg-badge' + (route.id === '4' ? ' dark' : '') + '" style="background:' + route.color + '">' + esc(TYPES[route.type].ar) + '</span>'
      + (route.loop ? '<span class="pt-pill">مسار دائري</span>' : '')
      + '</div>'
      + transfer
      + '<details><summary>محطات التوقّف (' + (leg.stopsIds.length) + ')</summary><ol>' + stopList + '</ol></details>'
      + '</div></li>';
  }

  function googleLink(it) {
    var a = state.from, b = state.to;
    return window.RMLinks
      ? window.RMLinks.googleMapsDirections({ origin: [a.lat, a.lng], destination: [b.lat, b.lng], travelmode: 'transit' })
      : 'https://www.google.com/maps';
  }

  function downloadJourney(it) {
    var fc = { type: 'FeatureCollection', features: it.legs.map(function (leg) {
      return {
        type: 'Feature',
        properties: { type: leg.type, line: leg.line || leg.route || null, minutes: leg.minutes, meters: leg.meters },
        geometry: { type: 'LineString', coordinates: leg.geometry.map(function (p) { return [p[1], p[0]]; }) }
      };
    }) };
    var blob = new Blob([JSON.stringify(fc, null, 1)], { type: 'application/geo+json' });
    var a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'riyadh-journey.geojson';
    a.click();
    setTimeout(function () { URL.revokeObjectURL(a.href); }, 4000);
  }

  /* ────────────────────────────────────────────────── 7. journey map */
  function clearJourney() { groups.journey.clearLayers(); }

  function drawJourney(it) {
    clearJourney();
    it.legs.forEach(function (leg) {
      if (!leg.geometry || leg.geometry.length < 2) return;
      var style;
      if (leg.type === 'walk') style = { color: isLight() ? '#5b6b62' : '#c8d6cd', weight: 3, opacity: 0.85, dashArray: '2 7', lineCap: 'round' };
      else if (leg.type === 'metro') style = { color: NET.lines[leg.line].color, weight: 6, opacity: 0.95 };
      else style = { color: MODEL.routes[leg.route].color, weight: 5, opacity: 0.95 };
      var pl = L.polyline(leg.geometry, Object.assign(style, { lineJoin: 'round' }));
      pl.bindTooltip(leg.type === 'walk' ? 'مشي ' + dist(leg.meters) : leg.type === 'metro' ? 'مترو ' + nm(NET.lines[leg.line].name) : 'حافلة ' + leg.route, { sticky: true });
      pl.addTo(groups.journey);
      if (leg.type === 'walk') return;
    });
    var first = it.legs[0];
    var last = it.legs[it.legs.length - 1];
    var startPt = first.geometry && first.geometry[0];
    var endPt = last.geometry && last.geometry[last.geometry.length - 1];
    if (startPt) L.circleMarker(startPt, { radius: 8, color: '#fff', weight: 3, fillColor: '#22c07a', fillOpacity: 1 }).bindTooltip('الانطلاق', { permanent: false }).addTo(groups.journey);
    if (endPt) L.circleMarker(endPt, { radius: 8, color: '#fff', weight: 3, fillColor: '#ef5350', fillOpacity: 1 }).bindTooltip('الوصول', { permanent: false }).addTo(groups.journey);
    fitJourney(it);
  }

  function fitJourney(it) {
    var pts = [];
    it.legs.forEach(function (l) { (l.geometry || []).forEach(function (p) { pts.push(p); }); });
    if (pts.length) map.fitBounds(L.latLngBounds(pts), { padding: [36, 36], maxZoom: 15 });
  }

  /* ────────────────────────────────────────────────── 8. bus routes tab */
  function renderTypeFilters() {
    var counts = { all: MODEL.routeOrder.length, brt: 0, main: 0, sector: 0, community: 0 };
    MODEL.routeOrder.forEach(function (id) { counts[MODEL.routes[id].type]++; });
    var items = [['all', 'الكل', '#8ba396']].concat(Object.keys(TYPES).map(function (t) { return [t, TYPES[t].long, TYPES[t].color]; }));
    $('#pt-type-filters').innerHTML = items.map(function (x) {
      return '<button type="button" data-type="' + x[0] + '" aria-pressed="' + (state.busFilter === x[0]) + '">'
        + '<span class="swatch" style="background:' + x[2] + '"></span>' + esc(x[1]) + ' (' + counts[x[0]] + ')</button>';
    }).join('');
    $$('#pt-type-filters button').forEach(function (b) {
      b.addEventListener('click', function () {
        state.busFilter = b.dataset.type;
        renderTypeFilters();
        renderBusList();
      });
    });
  }

  function routeMatchesQuery(r, q) {
    if (!q) return true;
    var text = [r.id, nm(r.name), ne(r.name), nm(r.origin), nm(r.destination), ne(r.origin), ne(r.destination)].join(' ').toLowerCase();
    return text.indexOf(q) >= 0;
  }

  function renderBusList() {
    var q = state.busQuery.trim().toLowerCase();
    var list = MODEL.routeOrder.filter(function (id) {
      var r = MODEL.routes[id];
      if (state.busFilter !== 'all' && r.type !== state.busFilter) return false;
      return routeMatchesQuery(r, q);
    });
    $('#pt-bus-hint').textContent = 'عرض ' + list.length + ' من ' + MODEL.routeOrder.length + ' مساراً' + (q ? ' · البحث: «' + q + '»' : '');
    var html = list.map(function (id) {
      var r = MODEL.routes[id];
      var light = r.id === '4';
      return '<button class="pt-card' + (state.route === id ? ' active' : '') + '" data-route="' + id + '">'
        + '<span class="num' + (light ? ' light' : '') + '" style="background:' + r.color + '">' + r.id + '</span>'
        + '<span class="copy"><b>' + esc(nm(r.name)) + '</b><small>' + esc(TYPES[r.type].long) + ' · ' + r.stopCount + ' محطة · كل ' + r.headwayMin + ' د</small></span>'
        + '<span class="meta"><b>' + km(r.lengthM) + ' كم</b>' + r.runtimeMin + ' د</span>'
        + '</button>';
    }).join('');
    $('#pt-bus-list').innerHTML = list.length ? '<div class="pt-list">' + html + '</div>' : '<p class="hint">لا يوجد مسار مطابق. جرّب رقماً مثل 11 أو 930.</p>';
    $$('#pt-bus-list [data-route]').forEach(function (b) {
      b.addEventListener('click', function () { focusRoute(b.dataset.route); });
    });
    if (!list.length && q.length > 2) {
      var stopHits = MODEL.stopOrder.filter(function (sid) {
        return nm(MODEL.stops[sid].name).toLowerCase().indexOf(q) >= 0;
      }).slice(0, 6);
      if (stopHits.length) {
        $('#pt-bus-list').insertAdjacentHTML('afterbegin', '<p class="pt-section-mini">محطات توقّف مطابقة</p><div class="pt-list">'
          + stopHits.map(function (sid) {
            var s = MODEL.stops[sid];
            return '<button class="pt-card" data-stop="' + sid + '"><span class="num" style="background:#2D7DD2">' + s.code.slice(-3) + '</span>'
              + '<span class="copy"><b>' + esc(nm(s.name)) + '</b><small>' + esc(MODEL.districts[s.district] ? nm(MODEL.districts[s.district].name) : '') + '</small></span>'
              + '<span class="meta"><b>' + s.routes.length + '</b>مسار</span></button>';
          }).join('') + '</div>');
        $$('#pt-bus-list [data-stop]').forEach(function (b) {
          b.addEventListener('click', function () { openStop(b.dataset.stop); });
        });
      }
    }
  }

  function renderBusDetail() {
    var box = $('#pt-bus-detail');
    if (!state.route) { box.innerHTML = ''; return; }
    var r = MODEL.routes[state.route];
    var dir = state.routeDir || Object.keys(r.dirs)[0];
    var d = r.dirs[dir];
    var dirs = Object.keys(r.dirs);
    var stops = d.stops.map(function (sid) { return MODEL.stops[sid]; }).filter(Boolean);
    box.innerHTML = '<div class="pt-detail">'
      + '<div class="pt-detail-head">'
      + '<span class="num" style="background:' + r.color + ';color:' + (r.id === '4' ? '#1a1a00' : '#fff') + '">' + r.id + '</span>'
      + '<div><b>' + esc(nm(r.name)) + '</b><small>' + esc(TYPES[r.type].long) + ' · ' + esc(nm(r.origin)) + ' ← ' + esc(nm(r.destination)) + '</small></div>'
      + '<button class="pt-detail-close" data-act="close">✕</button></div>'
      + '<div class="pt-kv">'
      + '<div><b>' + r.stopCount + '</b><span>محطة توقّف</span></div>'
      + '<div><b>' + km(r.lengthM) + '</b><span>كم</span></div>'
      + '<div><b>' + r.runtimeMin + '</b><span>دقيقة</span></div>'
      + '<div><b>' + r.headwayMin + '</b><span>دقيقة تردد</span></div>'
      + '<div><b>' + dirs.length + '</b><span>اتجاه</span></div>'
      + '</div>'
      + (r.plannedStops ? '<p class="hint">منها ' + r.plannedStops + ' محطة في مراحل تطوير لاحقة (غير مفتوحة بعد).</p>' : '')
      + (dirs.length > 1 ? '<div class="pt-filters">' + dirs.map(function (x) {
        var dd = r.dirs[x];
        return '<button data-dir="' + x + '" aria-pressed="' + (x === dir) + '">' + (x === 'r' ? 'الاتجاه المعاكس' : 'اتجاه ' + x) + ' · ' + dd.stops.length + ' محطة</button>';
      }).join('') + '</div>' : '')
      + '<div class="pt-detail-actions">'
      + '<button data-act="map">اعرض على الخريطة</button>'
      + '<button data-act="from">ابدأ من أول محطة</button>'
      + '<button data-act="to">إلى آخر محطة</button>'
      + '</div>'
      + '<ol class="pt-stops">' + stops.map(function (s, i) {
        return '<li><button data-stop="' + s.id + '"><span class="seq">' + (i + 1) + '</span><span class="dot' + (s.shelter === 'brt' ? ' brt' : '') + '"></span>'
          + '<span>' + esc(nm(s.name)) + '</span><span class="tag">' + (SHELTER[s.shelter] ? SHELTER[s.shelter].short : '') + '</span></button></li>';
      }).join('') + '</ol>'
      + '</div>';
    var boxEl = $('#pt-bus-detail');
    $('[data-act="close"]', boxEl).addEventListener('click', function () {
      state.route = null;
      clearHighlight('route');
      renderBusDetail();
      renderBusList();
    });
    $$('[data-dir]', boxEl).forEach(function (b) {
      b.addEventListener('click', function () { focusRoute(r.id, { dir: b.dataset.dir, fit: false }); });
    });
    $$('[data-act="map"]', boxEl).forEach(function (b) { b.addEventListener('click', function () { focusRoute(r.id); }); });
    var firstStop = d.stops[0], lastStop = d.stops[d.stops.length - 1];
    $('[data-act="from"]', boxEl).addEventListener('click', function () { setEndpoint('from', { kind: 'stop', id: firstStop }); });
    $('[data-act="to"]', boxEl).addEventListener('click', function () { setEndpoint('to', { kind: 'stop', id: lastStop }); });
    $$('[data-stop]', boxEl).forEach(function (b) {
      b.addEventListener('click', function () { openStop(b.dataset.stop); });
    });
  }

  /* ────────────────────────────────────────────────── 9. districts tab */
  function shelterBreakdown(stops) {
    var counts = {};
    stops.forEach(function (s) { counts[s.shelter] = (counts[s.shelter] || 0) + 1; });
    return Object.keys(counts).sort(function (a, b) { return counts[b] - counts[a]; }).map(function (k) {
      return pill((SHELTER[k] ? SHELTER[k].ar : k) + ' ' + counts[k]);
    }).join('');
  }

  function renderAreaList() {
    var q = state.areaQuery.trim().toLowerCase();
    var list = MODEL.districtOrder.filter(function (id) {
      if (!q) return true;
      var d = MODEL.districts[id];
      return nm(d.name).toLowerCase().indexOf(q) >= 0 || ne(d.name).toLowerCase().indexOf(q) >= 0 || id.indexOf(q) >= 0;
    });
    var empty = MODEL.districtOrder.filter(function (id) { return !MODEL.districts[id].stops; }).length;
    $('#pt-area-list').innerHTML = (q ? '' : '<p class="hint">' + fmt(MODEL.districtOrder.length) + ' حياً · ' + fmt(MODEL.districtOrder.length - empty) + ' حياً مخدوماً بمحطات توقّف · ' + empty + ' أحياء خارج نطاق الشبكة المنشورة.</p>')
      + '<div class="pt-list">' + list.map(function (id) {
        var d = MODEL.districts[id];
        return '<button class="pt-card' + (state.district === id ? ' active' : '') + '" data-area="' + id + '">'
          + '<span class="num" style="background:' + (d.stops ? '#2FA37C' : '#7C8794') + '">' + d.stops + '</span>'
          + '<span class="copy"><b>' + esc(nm(d.name)) + '</b><small>' + esc(ne(d.name)) + (d.approx ? ' · حدود تقريبية' : '') + '</small></span>'
          + '<span class="meta"><b>' + d.routes.length + '</b>مسار' + (d.brtStops ? ' · BRT' : '') + '</span>'
          + '</button>';
      }).join('') + '</div>';
    $$('#pt-area-list [data-area]').forEach(function (b) {
      b.addEventListener('click', function () { focusDistrict(b.dataset.area); });
    });
  }

  function renderAreaDetail() {
    var box = $('#pt-area-detail');
    if (!state.district) { box.innerHTML = ''; return; }
    var d = MODEL.districts[state.district];
    var stops = RMTransit.districtStops(MODEL, state.district);
    var operating = stops.filter(function (s) { return s.operating; });
    var shown = stops.slice(0, 300);
    box.innerHTML = '<div class="pt-detail">'
      + '<div class="pt-detail-head"><span class="num" style="background:#2FA37C">' + d.stops + '</span>'
      + '<div><b>حي ' + esc(nm(d.name)) + '</b><small>' + esc(ne(d.name)) + ' · ' + (d.approx ? 'حدود تقريبية' : 'حدود موثّقة') + '</small></div>'
      + '<button class="pt-detail-close" data-act="close">✕</button></div>'
      + '<div class="pt-kv">'
      + '<div><b>' + d.stops + '</b><span>محطة توقّف</span></div>'
      + '<div><b>' + operating.length + '</b><span>قيد التشغيل</span></div>'
      + '<div><b>' + d.routes.length + '</b><span>مسار</span></div>'
      + '<div><b>' + d.brtStops + '</b><span>محطة BRT</span></div>'
      + '</div>'
      + '<div class="pt-leg-badges">' + shelterBreakdown(stops) + '</div>'
      + '<div class="pt-detail-actions"><button data-act="map">اعرض الحي</button><button data-act="plan">خطّط من الحي</button></div>'
      + '<p class="pt-section-mini">محطات الوقوف والركوب في الحي</p>'
      + '<ol class="pt-stops">' + shown.map(function (s, i) {
        return '<li><button data-stop="' + s.id + '"><span class="seq">' + (i + 1) + '</span><span class="dot' + (s.shelter === 'brt' ? ' brt' : '') + '"></span>'
          + '<span>' + esc(nm(s.name)) + '</span><span class="tag">' + (s.operating ? (SHELTER[s.shelter] ? SHELTER[s.shelter].short : '') : 'قادمة') + '</span></button></li>';
      }).join('') + '</ol>'
      + (stops.length > shown.length ? '<p class="hint">و' + fmt(stops.length - shown.length) + ' محطة أخرى في هذا الحي.</p>' : '')
      + '<p class="pt-section-mini">المسارات المخدومة</p>'
      + '<div class="pt-leg-badges">' + d.routes.map(function (rid) {
        var r = MODEL.routes[rid];
        return '<button class="pt-leg-badge" data-route="' + rid + '" style="background:' + (r ? r.color : '#7C8794') + ';color:' + (rid === '4' ? '#1a1a00' : '#fff') + ';border:0;cursor:pointer">' + rid + '</button>';
      }).join('') + '</div>'
      + '</div>';
    var el = $('#pt-area-detail');
    $('[data-act="close"]', el).addEventListener('click', function () {
      state.district = null;
      clearHighlight('district');
      renderAreaDetail();
      renderAreaList();
    });
    $('[data-act="map"]', el).addEventListener('click', function () { focusDistrict(d.id); });
    $('[data-act="plan"]', el).addEventListener('click', function () {
      setEndpoint('from', { kind: 'coord', name: { ar: 'حي ' + nm(d.name), en: nm(d.name) }, lat: d.centroid[0], lng: d.centroid[1], district: d.id });
      switchTab('plan');
      $('#pt-to').focus();
    });
    $$('[data-stop]', el).forEach(function (b) { b.addEventListener('click', function () { openStop(b.dataset.stop); }); });
    $$('[data-route]', el).forEach(function (b) { b.addEventListener('click', function () { focusRoute(b.dataset.route); }); });
  }

  /* ──────────────────────────────────────────── 10. station / stop card */
  function renderStopCard(s) {
    var box = $('#pt-results');
    var routes = s.routes.map(function (rid) { return MODEL.routes[rid]; }).filter(Boolean);
    var metro = s.nearMetro ? '<p class="hint">أقرب محطة مترو: ' + esc(stationName(s.nearMetro.station)) + ' · ' + dist(s.nearMetro.distanceM) + '</p>' : '';
    box.innerHTML = '<div class="pt-result-head"><b>محطة توقّف</b></div>'
      + '<div class="pt-detail"><div class="pt-detail-head">'
      + '<span class="num" style="background:' + stopColor(s) + '">' + (s.shelter === 'brt' ? 'BRT' : '🚌') + '</span>'
      + '<div><b>' + esc(nm(s.name)) + '</b><small dir="ltr">' + esc(ne(s.name)) + ' · ' + esc(s.code) + '</small></div></div>'
      + '<div class="pt-kv"><div><b>' + routes.length + '</b><span>مسار</span></div>'
      + '<div><b>' + (s.operating ? '✔' : '⏳') + '</b><span>' + (s.operating ? 'يعمل' : 'قادم') + '</span></div>'
      + '<div><b>' + esc(MODEL.districts[s.district] ? nm(MODEL.districts[s.district].name) : '—') + '</b><span>الحي</span></div></div>'
      + metro
      + '<div class="pt-leg-badges">' + routes.map(function (r) {
        return '<button class="pt-leg-badge" data-route="' + r.id + '" style="background:' + r.color + ';color:' + (r.id === '4' ? '#1a1a00' : '#fff') + ';border:0;cursor:pointer">' + r.id + '</button>';
      }).join('') + '</div>'
      + '<div class="pt-detail-actions"><button data-act="from">ابدأ من هنا</button><button data-act="to">إلى هنا</button></div></div>';
    var el = $('#pt-results');
    $$('[data-route]', el).forEach(function (b) { b.addEventListener('click', function () { focusRoute(b.dataset.route); }); });
    $('[data-act="from"]', el).addEventListener('click', function () { setEndpoint('from', { kind: 'stop', id: s.id }); switchTab('plan'); });
    $('[data-act="to"]', el).addEventListener('click', function () { setEndpoint('to', { kind: 'stop', id: s.id }); switchTab('plan'); });
    $('#pt-plan-empty').hidden = true;
  }

  function renderStationCard(st, near, routes, pr) {
    var box = $('#pt-results');
    var stopList = near.slice(0, 12).map(function (x) {
      var s = MODEL.stops[x.stop];
      return '<li><button data-stop="' + s.id + '"><span class="dot"></span><span>' + esc(nm(s.name)) + '</span><span class="tag">' + dist(x.distanceM) + '</span></button></li>';
    }).join('');
    box.innerHTML = '<div class="pt-result-head"><b>محطة مترو</b></div>'
      + '<div class="pt-detail"><div class="pt-detail-head">'
      + '<span class="num" style="background:#1f1f1f">🚇</span>'
      + '<div><b>' + esc(nm(st.name)) + '</b><small>' + st.lines.map(function (l) { return esc(nm(NET.lines[l].name)); }).join(' · ') + '</small></div></div>'
      + '<div class="pt-kv"><div><b>' + near.length + '</b><span>محطة باص</span></div>'
      + '<div><b>' + Object.keys(routes).length + '</b><span>مسار</span></div>'
      + '<div><b>' + (pr && pr.capacity ? fmt(pr.capacity) : '—') + '</b><span>موقف P+R</span></div></div>'
      + (near.length ? '<p class="pt-section-mini">محطات الوقوف والركوب القريبة (≤ 450 م)</p><ol class="pt-stops">' + stopList + '</ol>' : '<p class="hint">لا توجد محطات حافلات منشورة ضمن 450 م من هذه المحطة.</p>')
      + '<div class="pt-detail-actions"><button data-act="from">ابدأ من هنا</button><button data-act="to">إلى هنا</button></div></div>';
    var el = $('#pt-results');
    $$('[data-stop]', el).forEach(function (b) { b.addEventListener('click', function () { openStop(b.dataset.stop); }); });
    $('[data-act="from"]', el).addEventListener('click', function () { setEndpoint('from', { kind: 'station', id: st.id }); });
    $('[data-act="to"]', el).addEventListener('click', function () { setEndpoint('to', { kind: 'station', id: st.id }); });
    $('#pt-plan-empty').hidden = true;
  }

  /* ────────────────────────────────────────────────── 11. parking tab */
  function renderParking() {
    var sites = PR.sites.slice().sort(function (a, b) { return (b.capacity || 0) - (a.capacity || 0); });
    var spaces = PR.sites.reduce(function (n, s) { return n + (s.capacity || 0); }, 0);
    var rules = PR.rules || {};
    var inter = RMTransit.interchangeRanking(MODEL).slice(0, 10);
    var noBus = RMTransit.interchangeRanking(MODEL).filter(function (x) { return !x.stops; });
    var html = '<p class="pt-section-mini">اركن واركب · ' + sites.length + ' موقفاً بسعة منشورة (19 موقعاً معلناً) · ' + fmt(spaces) + ' موقف سيارة</p>'
      + '<div class="pt-list">' + sites.map(function (s) {
        return '<button class="pt-card" data-pr="' + s.station + '">'
          + '<span class="num" style="background:#0f766e">🅿️</span>'
          + '<span class="copy"><b>' + esc(nm(s.name)) + '</b><small>' + (s.lines || []).map(function (l) { return 'مترو ' + l; }).join(' · ') + (s.confidence === 'reported' ? ' · سعة معلنة' : '') + '</small></span>'
          + '<span class="meta"><b>' + (s.capacity ? fmt(s.capacity) : '—') + '</b>موقف</span></button>';
      }).join('') + '</div>'
      + '<p class="pt-section-mini">قواعد الاستخدام</p>'
      + '<ul class="pt-rule-list">'
      + (rules.access ? '<li>' + esc(nm(rules.access)) + '</li>' : '')
      + (rules.freeMinutes ? '<li>' + rules.freeMinutes + ' دقيقة مجانية للإنزال والتحميل.</li>' : '')
      + (rules.freeHoursWithTransit ? '<li>مجاناً حتى ' + rules.freeHoursWithTransit + ' ساعة عند استخدام البطاقة نفسها في المترو أو الحافلة.</li>' : '')
      + (rules.maxHours ? '<li>الحد الأقصى ' + rules.maxHours + ' ساعة، وبعدها ' + (rules.hourlyAfterFreeSar || 10) + ' ر.س لكل ساعة إضافية.</li>' : '')
      + (rules.speedLimitKmh ? '<li>السرعة داخل الموقف ' + rules.speedLimitKmh + ' كم/س.</li>' : '')
      + (rules.opening ? '<li>' + esc(nm(rules.opening)) + '</li>' : '')
      + (rules.notAllowed ? '<li>ممنوع: ' + esc(nm(rules.notAllowed)) + '</li>' : '')
      + '</ul>'
      + (PR.busParking ? '<p class="pt-section-mini">مواقف مستخدمي الحافلات</p><p class="hint">' + esc(nm(PR.busParking.note)) + '</p>' : '')
      + '<p class="pt-section-mini">مراكز الانتقال: مترو ↔ حافلة</p>'
      + '<p class="hint">المحطات التي تخدمها أكبر عدد من مسارات الحافلات ضمن 450 م.</p>'
      + '<div class="pt-list">' + inter.map(function (x) {
        return '<button class="pt-card" data-station="' + x.station.id + '">'
          + '<span class="num" style="background:#1f1f1f">' + x.routes + '</span>'
          + '<span class="copy"><b>' + esc(nm(x.station.name)) + '</b><small>' + x.stops + ' محطة باص · ' + (x.station.lines || []).map(function (l) { return 'مترو ' + l; }).join(' · ') + '</small></span>'
          + '<span class="meta"><b>' + dist(x.nearestM || 0) + '</b>أقرب موقف</span></button>';
      }).join('') + '</div>'
      + (noBus.length ? '<p class="pt-section-mini">محطات مترو بلا حافلات قريبة (' + noBus.length + ')</p><p class="hint">'
        + noBus.map(function (x) { return esc(nm(x.station.name)); }).join(' · ') + '</p>' : '')
      + '<p class="pt-section-mini">المصادر</p>'
      + '<ul class="pt-rule-list">' + (PR.sources || []).map(function (src) {
        var label = src.label || src.name || src.url || '';
        return '<li>' + (src.url ? '<a href="' + esc(src.url) + '" target="_blank" rel="noopener">' + esc(label) + '</a>' : esc(label)) + (src.note ? ' — ' + esc(nm(src.note)) : '') + '</li>';
      }).join('') + '</ul>';
    $('#pt-parking-content').innerHTML = html;
    $$('#pt-parking-content [data-pr]').forEach(function (b) {
      b.addEventListener('click', function () {
        var site = PR.byStation[b.dataset.pr];
        map.setView([site.lat, site.lng], 15);
        openParking(site);
      });
    });
    $$('#pt-parking-content [data-station]').forEach(function (b) {
      b.addEventListener('click', function () { openStation(b.dataset.station); });
    });
  }

  function renderParkingOverview() {
    var spaces = PR.sites.reduce(function (n, s) { return n + (s.capacity || 0); }, 0);
    var linked = Object.keys(NET.stations).filter(function (id) { return (MODEL.stationStops[id] || []).length > 0; }).length;
    var top = PR.sites.slice().sort(function (a, b) { return (b.capacity || 0) - (a.capacity || 0); }).slice(0, 4);
    var cards = [
      { t: 'مواقف اركن واركب', v: PR.sites.length + ' موقعاً', d: fmt(spaces) + ' موقف سيارة مسجّل على شبكة المترو (من أصل 19 موقعاً معلناً).', href: '#pt-parking' },
      { t: 'مراكز الانتقال', v: 'مترو ↔ حافلة', d: linked + ' من ' + Object.keys(NET.stations).length + ' محطة يخدمها موقف حافلة ضمن 450 م.', href: '#pt-app' },
      { t: 'مواقف الحافلات', v: (PR.busParking && PR.busParking.count ? PR.busParking.count : 4) + ' مواقع', d: 'مخصّصة لمستخدمي الحافلات ومرتبطة بالمترو، بسعة 200–600 سيارة.', href: '#pt-parking' }
    ];
    $('#pt-parking-overview').innerHTML = cards.map(function (c) {
      return '<article class="pt-parking-card"><header><b>' + esc(c.t) + '</b></header>'
        + '<p style="font-size:16px;color:var(--ink);font-weight:700;margin:2px 0 6px">' + esc(c.v) + '</p>'
        + '<p>' + esc(c.d) + '</p></article>';
    }).join('') + top.map(function (s) {
      return '<article class="pt-parking-card"><header><b>' + esc(nm(s.name)) + '</b><span class="lines">'
        + (s.lines || []).map(function (l) { return '<i style="background:' + NET.lines[l].color + '"></i>'; }).join('')
        + '</span></header><p><b style="color:var(--ink);font-size:15px">' + (s.capacity ? fmt(s.capacity) : '—') + '</b> موقفاً · ' + (s.confidence === 'reported' ? 'سعة معلنة' : 'تقديري') + '</p></article>';
    }).join('');

    var rules = PR.rules || {};
    $('#pt-rules').innerHTML = '<h3>كيف يعمل «اركن واركب»؟</h3><ul>'
      + '<li>' + esc(nm(rules.access || { ar: 'الدخول ببطاقة درب.' })) + '</li>'
      + '<li>أول ' + (rules.freeMinutes || 15) + ' دقيقة مجانية للإنزال والتحميل.</li>'
      + '<li>مجاناً حتى ' + (rules.freeHoursWithTransit || 12) + ' ساعة إذا استخدمت البطاقة نفسها في المترو أو الحافلة.</li>'
      + '<li>بعد ذلك ' + (rules.hourlyAfterFreeSar || 10) + ' ر.س لكل ساعة، بحد أقصى ' + (rules.maxHours || 48) + ' ساعة.</li>'
      + '<li>' + esc(nm(rules.notAllowed || { ar: '' })) + '</li>'
      + '</ul>';
  }

  /* ────────────────────────────────────────────────── 12. static panels */
  function renderHero() {
    var stats = [
      { v: fmt(S.routes), l: 'مسار حافلات' },
      { v: fmt(S.stops), l: 'محطة توقّف' },
      { v: fmt(S.stations), l: 'محطة مترو' },
      { v: fmt(S.districts), l: 'حيّاً' },
      { v: fmt(PR.sites.length), l: 'موقفاً بسعة منشورة' }
    ];
    $('#pt-stats').innerHTML = stats.map(function (s) { return '<li><b>' + s.v + '</b><span>' + s.l + '</span></li>'; }).join('');

    var covered = MODEL.districtOrder.filter(function (id) { return MODEL.districts[id].stops > 0; }).length;
    var spaces = PR.sites.reduce(function (n, s) { return n + (s.capacity || 0); }, 0);
    var busHours = (CFG.service && CFG.service.busHours && CFG.service.busHours[0]) || null;
    var hours = (CFG.service && CFG.service.hours && CFG.service.hours[0]) || null;
    var fare = 4;
    try { fare = CFG.fares.tickets[0].price; } catch (e) { /* default */ }
    var facts = [
      ['مسارات الحافلات', fmt(S.routes) + ' · BRT ' + fmt(MODEL.routeOrder.filter(function (id) { return MODEL.routes[id].type === 'brt'; }).length)],
      ['محطات التوقّف', fmt(S.stops) + ' · ' + fmt(S.operatingStops) + ' قيد التشغيل'],
      ['محطات المترو', fmt(S.stations) + ' محطة · 6 مسارات'],
      ['الأحياء المخدومة', fmt(covered) + ' من ' + fmt(S.districts)],
      ['المواقف', fmt(PR.sites.length) + ' موقعاً · ' + fmt(spaces) + ' موقفاً'],
      ['ساعات الحافلات', busHours ? busHours.open + ' – ' + (busHours.close === '24:00' ? '24:00' : busHours.close) : '05:00 – 24:00'],
      ['الترددات', '7 – 25 دقيقة'],
      ['الأجرة', fare + ' ر.س للرحلة على المترو والحافلات']
    ];
    if (hours) facts[6][1] = hours.open + ' – ' + (hours.close === '24:00' ? '24:00' : hours.close);
    $('#pt-facts').innerHTML = facts.map(function (f) { return '<div><dt>' + esc(f[0]) + '</dt><dd>' + esc(f[1]) + '</dd></div>'; }).join('');
  }

  function renderQuick() {
    var trips = (CFG.popularTrips || []).slice(0, 4);
    var html = trips.map(function (t) {
      var a = NET.stations[t.from], b = NET.stations[t.to];
      if (!a || !b) return '';
      var label = t.label ? nm(t.label) : nm(a.name) + ' ← ' + nm(b.name);
      return '<button type="button" data-from="' + t.from + '" data-to="' + t.to + '">' + esc(label) + '</button>';
    }).join('');
    html += '<button type="button" data-from="stop" data-to="station">🚌 من محطة حافلة في العليا إلى المركز المالي</button>';
    $('#pt-quick').innerHTML = html;
    $$('#pt-quick button').forEach(function (b) {
      b.addEventListener('click', function () {
        if (b.dataset.from === 'stop') {
          var primary = MODEL.stopOrder.filter(function (id) {
            return MODEL.stops[id].district === 'al-olaya' && MODEL.stops[id].routes.length;
          })[0] || MODEL.stopOrder[0];
          var s = MODEL.stops[primary];
          setEndpoint('from', { kind: 'stop', id: s.id });
          setEndpoint('to', { kind: 'station', id: 'kafd' });
          return;
        }
        setEndpoint('from', { kind: 'station', id: b.dataset.from });
        setEndpoint('to', { kind: 'station', id: b.dataset.to });
      });
    });
  }

  function renderDataCards() {
    var cards = [
      { t: 'GTFS كامل (مترو + حافلات)', d: 'جدول زمني ترددي قابل للتحميل في أي تطبيق نقل عام.', u: '../dist/gtfs/riyadh-transit-gtfs.zip' },
      { t: 'GeoJSON — مسارات الحافلات', d: '117 اتجاهاً مع الهندسة الكاملة لكل مسار.', u: '../dist/riyadh-bus-routes.geojson' },
      { t: 'GeoJSON — محطات التوقّف', d: '3,010 محطة مع النوع والحي وحالة التشغيل.', u: '../dist/riyadh-bus-stops.geojson' },
      { t: 'GeoJSON — الأحياء', d: '133 حياً مع أعداد المحطات والمسارات.', u: '../dist/riyadh-districts.geojson' },
      { t: 'GeoJSON — المواقف', d: 'مواقف اركن واركب عند محطات المترو.', u: '../dist/riyadh-park-and-ride.geojson' },
      { t: 'CSV — جداول البيانات', d: 'محطات ومسارات للتحميل إلى Excel أو Google Sheets.', u: '../dist/riyadh-bus-stops.csv' }
    ];
    $('#pt-data-grid').innerHTML = cards.map(function (c) {
      return '<article class="pt-data-card"><b>' + esc(c.t) + '</b><small>' + esc(c.d) + '</small>'
        + '<a href="' + c.u + '" download>تنزيل ↓</a></article>';
    }).join('') + '<article class="pt-data-card"><b>مصادر البيانات</b><small>البيانات المفتوحة للهيئة الملكية لمدينة الرياض (2024) وحدود الأحياء الموثّقة.</small>'
      + '<a href="../data/SOURCES.md">اقرأ المصادر ←</a></article>';
  }

  function renderLegend() {
    var items = NET.lineOrder.map(function (lid) {
      return '<span><i style="background:' + NET.lines[lid].color + '"></i>' + esc(nm(NET.lines[lid].name)) + '</span>';
    });
    items.push('<span><i style="background:' + TYPES.brt.color + '"></i>BRT</span>');
    items.push('<span><i style="background:' + TYPES.main.color + '"></i>رئيسي</span>');
    items.push('<span><i style="background:' + TYPES.sector.color + '"></i>قطاعي</span>');
    items.push('<span><i style="background:' + TYPES.community.color + '"></i>تغذية</span>');
    items.push('<span><i class="dot" style="background:#E8552D"></i>محطة BRT</span>');
    $('#pt-legend').innerHTML = items.join('');
  }

  function renderLayers() {
    var defs = [
      ['metro', 'المترو ومحطاته', '#00ADE5', 'metro'],
      ['bus', 'مسارات الحافلات', '#2D7DD2', 'bus'],
      ['stops', 'محطات التوقّف (تكبير ≥ 13)', '#7C8794', 'stops'],
      ['parking', 'مواقف اركن واركب', '#0f766e', 'parking'],
      ['districts', 'حدود الأحياء', '#2FA37C', 'districts'],
      ['labels', 'أسماء الأحياء وأعداد المحطات', '#8ba396', 'labels']
    ];
    $('#pt-layers').innerHTML = defs.map(function (d) {
      return '<label><input type="checkbox" data-layer="' + d[0] + '"' + (state.layers[d[0]] ? ' checked' : '') + '>'
        + '<span class="swatch" style="background:' + d[2] + '"></span>' + d[3] + '</label>';
    }).join('');
    $$('#pt-layers input').forEach(function (el) {
      el.addEventListener('change', function () {
        state.layers[el.dataset.layer] = el.checked;
        if (el.dataset.layer === 'stops' || el.dataset.layer === 'labels') { /* redraw */ }
        applyLayers();
      });
    });
    $('#pt-layers-toggle').addEventListener('click', function () {
      var box = $('#pt-layers');
      var open = box.hidden;
      box.hidden = !open;
      this.setAttribute('aria-expanded', String(open));
    });
  }

  function renderClock() {
    var el = $('#pt-clock');
    function tick() {
      try {
        el.textContent = new Intl.DateTimeFormat('ar-SA', {
          timeZone: 'Asia/Riyadh', hour: '2-digit', minute: '2-digit', hour12: false
        }).format(new Date()) + ' · الرياض';
      } catch (e) { el.textContent = 'الرياض'; }
    }
    tick();
    setInterval(tick, 30000);
  }

  /* ────────────────────────────────────────────────── 13. tabs & chrome */
  var tabIds = ['plan', 'bus', 'areas', 'parking'];
  function switchTab(name) {
    if (tabIds.indexOf(name) < 0) return;
    state.tab = name;
    tabIds.forEach(function (id) {
      var btn = $('#tab-' + id + '-btn');
      var panel = $('#tab-' + id);
      var on = id === name;
      btn.setAttribute('aria-selected', String(on));
      btn.tabIndex = on ? 0 : -1;
      panel.hidden = !on;
    });
    if (name === 'bus') { renderBusList(); renderBusDetail(); }
    if (name === 'areas') { renderAreaList(); renderAreaDetail(); }
    if (name === 'parking') renderParking();
  }

  $$('.pt-tabs button').forEach(function (btn) {
    btn.addEventListener('click', function () { switchTab(btn.dataset.tab); });
    btn.addEventListener('keydown', function (e) {
      var i = tabIds.indexOf(btn.dataset.tab);
      var next = null;
      if (e.key === 'ArrowRight') next = tabIds[(i + 1) % tabIds.length];
      if (e.key === 'ArrowLeft') next = tabIds[(i + tabIds.length - 1) % tabIds.length];
      if (next) { e.preventDefault(); switchTab(next); $('#tab-' + next + '-btn').focus(); }
    });
  });

  $$('[data-open-tab]').forEach(function (a) {
    a.addEventListener('click', function () { switchTab(a.dataset.openTab); });
  });

  $('#pt-bus-search').addEventListener('input', function () {
    state.busQuery = this.value;
    renderBusList();
  });
  $('#pt-area-search').addEventListener('input', function () {
    state.areaQuery = this.value;
    renderAreaList();
  });

  $('#pt-zoom-in').addEventListener('click', function () { map.zoomIn(); });
  $('#pt-zoom-out').addEventListener('click', function () { map.zoomOut(); });
  $('#pt-fit').addEventListener('click', function () { map.fitBounds(L.latLngBounds([[24.45, 46.35], [25.05, 47.05]]), { padding: [20, 20] }); });

  $('#pt-theme').addEventListener('click', function () {
    var next = isLight() ? 'dark' : 'light';
    document.documentElement.setAttribute('data-theme', next);
    safeSet('rm.theme', next);
    map.removeLayer(base);
    base = baseLayers[next === 'light' ? 'light' : 'dark'].addTo(map);
    this.textContent = next === 'light' ? '☀️' : '🌙';
    if (state.alts.length) drawJourney(state.alts[state.itIndex] || state.alts[0]);
  });
  $('#pt-theme').textContent = isLight() ? '☀️' : '🌙';

  document.addEventListener('click', function (e) {
    var b = e.target.closest('[data-act="allow-all"]');
    if (!b) return;
    $$('input[name="pt-mode"]').forEach(function (r) { r.checked = r.value === 'all'; });
    state.modes = ['metro', 'bus', 'walk'];
    planJourney();
  });

  /* ────────────────────────────────────────────────── 14. hash deep links */
  var hashInit = false;
  function setHash(str) {
    if (!hashInit) return;
    try { history.replaceState(null, '', str ? '#' + str : location.pathname + location.search); } catch (e) { /* file:// */ }
  }
  function readHash() {
    var raw = location.hash.replace(/^#/, '');
    if (!raw) return;
    var params = {};
    raw.split('&').forEach(function (kv) {
      var i = kv.indexOf('=');
      if (i > 0) params[kv.slice(0, i)] = decodeURIComponent(kv.slice(i + 1));
    });
    hashInit = true;
    if (params.r) { focusRoute(params.r, { dir: params.d, fit: true }); return; }
    if (params.a) { focusDistrict(params.a); return; }
    if (params.f) {
      var parts = params.f.split('~');
      var f = decodeRef(parts[0]), t = decodeRef(parts[1]);
      if (f && t) {
        state.from = f; state.to = t;
        $('#pt-from').value = refName(f);
        $('#pt-to').value = refName(t);
        if (params.m) {
          state.modes = params.m === 'bus' ? ['bus', 'walk'] : params.m === 'metro' ? ['metro', 'walk'] : ['metro', 'bus', 'walk'];
          $$('input[name="pt-mode"]').forEach(function (r) { r.checked = r.value === (params.m === 'all' ? 'all' : params.m); });
        }
        planJourney();
      }
    }
  }

  /* ────────────────────────────────────────────────── 15. boot */
  renderHero();
  renderQuick();
  renderLayers();
  renderLegend();
  renderDataCards();
  renderParkingOverview();
  renderTypeFilters();
  renderClock();
  drawMetro();
  drawBusRoutes();
  drawDistricts();
  drawParking();
  applyLayers();
  renderBusList();
  renderAreaList();
  renderParking();
  switchTab('plan');
  map.invalidateSize();
  setTimeout(function () { map.invalidateSize(); }, 250);
  readHash();
  hashInit = true;

  /* small public surface: deep links, embeds and the browser test suite */
  window.PT = {
    model: MODEL, net: NET, state: state, map: map,
    focusRoute: focusRoute, focusDistrict: focusDistrict, openStop: openStop, openStation: openStation,
    setEndpoint: setEndpoint, planJourney: planJourney, switchTab: switchTab
  };
})();
